fn compute(op: Str, a: Int, b: Int) -> Result[Int, Str] {
    if op == "+" {
        return Ok(a + b)
    }
    if op == "-" {
        return Ok(a - b)
    }
    if op == "*" {
        return Ok(a * b)
    }
    if b == 0 {
        return Err("division by zero")
    }
    return Ok(a / b)
}

