            } else if c == "-" && expect_operand {
                ops.push("neg")
            } else if c == ")" || c == "+" || c == "-" || c == "*" || c == "/" {
                if expect_operand {
                    return Err("syntax error")
                }
                var p = 0
                if c != ")" {
                    p = prec(c)
                }
                while ops.len() > 0 {
                    let top = ops[ops.len() - 1]
                    if top == "(" || prec(top) < p {
                        break
                    }
                    ops.pop()
                    if top == "neg" {
                        if values.len() < 1 {
                            return Err("syntax error")
                        }
                        let a = values.pop()
                        values.push(0 - a)
                    } else {
                        if values.len() < 2 {
                            return Err("syntax error")
                        }
                        let b = values.pop()
                        let a = values.pop()
                        match compute(top, a, b) {
                            Ok(v) => {
                                values.push(v)
                            }
                            Err(e) => {
                                return Err(e)
                            }
                        }
                    }
                }
                if c == ")" {
                    if ops.len() == 0 {
                        return Err("syntax error")
                    }
                    ops.pop()
                    expect_operand = false
                } else {
                    ops.push(c)
                    expect_operand = true
                }
            } else {
                return Err("syntax error")
            }
        }
    }

    if in_num {
        values.push(num)
        expect_operand = false
    }
    if expect_operand {
        return Err("syntax error")
    }

    while ops.len() > 0 {
        let top = ops[ops.len() - 1]
        if top == "(" {
            return Err("syntax error")
        }
        ops.pop()
        if top == "neg" {
            if values.len() < 1 {
                return Err("syntax error")
            }
            let a = values.pop()
            values.push(0 - a)
        } else {
            if values.len() < 2 {
                return Err("syntax error")
            }
            let b = values.pop()
            let a = values.pop()
