fn tok_at(tokens: List[Str], i: Int) -> Str {
    match tokens.get(i) {
        Some(t) => {
            return t
        }
        None => {
            return ""
        }
    }
}

fn nth(xs: List[Int], i: Int) -> Int {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return 0
        }
    }
}

fn parse_primary(tokens: List[Str], start: Int) -> Result[List[Int], Str] {
    let t = tok_at(tokens, start)
    if t == "(" {
        match parse_expr(tokens, start + 1) {
            Err(e) => {
                return Err(e)
            }
            Ok(r) => {
                if tok_at(tokens, nth(r, 1)) != ")" {
                    return Err("syntax error")
                }
                return Ok([nth(r, 0), nth(r, 1) + 1])
            }
        }
    }
    if t == "" or t == "?" or t == "+" or t == "-" or t == "*" or t == "/" or t == ")" {
        return Err("syntax error")
    }
    var v = 0
    for c in t.chars() {
        v = v * 10 + digit_value(c)
    }
    return Ok([v, start + 1])
}

fn parse_unary(tokens: List[Str], start: Int) -> Result[List[Int], Str] {
    let t = tok_at(tokens, start)
    if t == "-" {
        match parse_unary(tokens, start + 1) {
            Err(e) => {
                return Err(e)
            }
            Ok(r) => {
                return Ok([0 - nth(r, 0), nth(r, 1)])
            }
        }
    }
    return parse_primary(tokens, start)
}

fn parse_term(tokens: List[Str], start: Int) -> Result[List[Int], Str] {
    match parse_unary(tokens, start) {
        Err(e) => {
            return Err(e)
        }
        Ok(first) => {
            var acc = nth(first, 0)
            var pos = nth(first, 1)
            var t = tok_at(tokens, pos)
            while t == "*" or t == "/" {
                match parse_unary(tokens, pos + 1) {
                    Err(e) => {
                        return Err(e)
                    }
                    Ok(rhs) => {
                        let v = nth(rhs, 0)
                        if t == "*" {
                            acc = acc * v
                        } else {
                            if v == 0 {
                                return Err("division by zero")
                            }
                            acc = acc / v
                        }
                        pos = nth(rhs, 1)
                    }
                }
                t = tok_at(tokens, pos)
            }
            return Ok([acc, pos])
        }
    }
}

fn parse_expr(tokens: List[Str], start: Int) -> Result[List[Int], Str] {
    match parse_term(tokens, start) {
        Err(e) => {
            return Err(e)
        }
        Ok(first) => {
            var acc = nth(first, 0)
            var pos = nth(first, 1)
            var t = tok_at(tokens, pos)
            while t == "+" or t == "-" {
                match parse_term(tokens, pos + 1) {
                    Err(e) => {
                        return Err(e)
                    }
                    Ok(rhs) => {
                        let v = nth(rhs, 0)
                        if t == "+" {
                            acc = acc + v
                        } else {
                            acc = acc - v
                        }
                        pos = nth(rhs, 1)
                    }
                }
                t = tok_at(tokens, pos)
            }
            return Ok([acc, pos])
        }
    }
}

pub fn calc(expr: Str) -> Result[Int, Str] {
    var tokens: List[Str] = []
    var cur = ""
    for c in expr.chars() {
        if is_digit(c) {
            cur = cur + c
        } else {
            if cur != "" {
                tokens.push(cur)
                cur = ""
            }
            if c != " " {
                if c == "+" or c == "-" or c == "*" or c == "/" or c == "(" or c == ")" {
                    tokens.push(c)
                } else {
                    tokens.push("?")
                }
            }
        }
    }
    if cur != "" {
        tokens.push(cur)
    }

    match parse_expr(tokens, 0) {
        Err(e) => {
            return Err(e)
        }
        Ok(r) => {
            if nth(r, 1) != tokens.len() {
                return Err("syntax error")
            }
            return Ok(nth(r, 0))
        }
    }
}
